<script lang="ts">
  import Panel from './Panel.svelte'; import Meter from './Meter.svelte';
  import Icon from '#lib/components/Icon.svelte'; import LineChart from '#lib/components/LineChart.svelte';
  import { apiGet } from '#lib/api/client.ts';
  import { number as n, text, rows, type Model, type Actions } from './model';
  let { m, a }: { m: Model; a: Actions } = $props();
  let goalFilter = $state(''); let schedule = $state<ReturnType<typeof rows> | null>(null); let selectedLoan = $state(0);
  let range = $state('1y'); let history = $state<ReturnType<typeof rows> | null>(null); let error = $state('');
  const goals = $derived(m.goals.filter(row => !goalFilter || row.status === goalFilter));
  const allocations = $derived(m.budgets.flatMap(budget => [
    ...rows(budget.categories).map(row=>({...row,allocated:n(row.allocated),spent:n(row.spent),rollover:n(row.rollover),label:m.category(row.categoryId)})),
    ...rows(budget.tags).map(row=>({...row,allocated:n(row.allocated),spent:n(row.spent),rollover:n(row.rollover),label:`# ${text(row.tagName)||row.tagId}`})),
  ]));
  const allocated = $derived(m.budgets.reduce((sum,row) => sum+n(row.totalAllocated),0));
  const rollover = $derived(allocations.reduce((sum,row)=>sum+n(row.rollover),0));
  const spent = $derived(m.budgets.reduce((sum,row) => sum+n(row.totalSpent),0));
  const monthly = $derived(m.loans.filter(row=>row.status!=='paid').reduce((sum,row) => { const p=n(row.principal), r=n(row.interestRate)/1200, months=n(row.term); return sum + (r ? p*r/(1-Math.pow(1+r,-months)) : months ? p/months : 0); },0));
  async function showSchedule(id: number) { try { error=''; schedule=rows(await apiGet(`/loans/${id}/schedule`)); selectedLoan=id; } catch(e) { error=e instanceof Error?e.message:String(e); } }
  async function changeRange(value: string) { try { error=''; history=rows(await apiGet('/networth/history',{range:value})); range=value; } catch(e) { error=e instanceof Error?e.message:String(e); } }
</script>
{#if error}<p class="cp-error" role="alert">{error}</p>{/if}
{#if m.route === 'presupuestos'}
  <div class="cp-tabs"><button class="active">{m.t('cyberpunk.overview')}</button><button onclick={() => a.edit('budgets')}>+ {m.t('cyberpunk.new_budget')}</button><button onclick={()=>a.edit('budgets',m.budgets[0])}>{m.t('cyberpunk.budget_settings')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.t('cyberpunk.monthly_income')}</span><strong class="cp-cyan">{m.money((m.dashboard.monthlySummary as Record<string,unknown>)?.totalIncome)}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.budgeted')}</span><strong>{m.money(allocated)}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.actual_spending')}</span><strong class="cp-red">{m.money(spent)}</strong></div><div class="cp-stat"><span>{m.t('dashboard.remaining')}</span><strong class="cp-yellow">{m.money(allocated+rollover-spent)}</strong></div></div>
  <Panel title={m.t('cyberpunk.budget_by_category')}>
    {#snippet action()}<button class="cp-button small ghost" onclick={() => a.edit('budgets')}>+ {m.t('cyberpunk.new_budget')}</button>{/snippet}
    <div class="cp-table-wrap"><table class="cp-table cp-budget-table"><thead><tr><th>{m.t('search.filter_category')}</th><th class="cp-right">{m.t('cyberpunk.allocated')}</th><th class="cp-right">{m.t('cyberpunk.spent')}</th><th class="cp-right">{m.t('dashboard.remaining')}</th><th>{m.t('loans.progress')}</th></tr></thead><tbody>{#each allocations as row,i}<tr><td>{row.label}</td><td class="cp-number cp-right">{m.money(row.allocated)}</td><td class="cp-number cp-red cp-right">{m.money(row.spent)}</td><td class="cp-number cp-cyan cp-right">{m.money(n(row.allocated)+n(row.rollover)-n(row.spent))}</td><td><div class="cp-progress-value"><span>{Math.round(n(row.spent)/Math.max(1,n(row.allocated))*100)}%</span><Meter value={n(row.spent)} max={n(row.allocated)} tone={n(row.spent)>n(row.allocated)*.9?'red':'cyan'} label={`${row.label} ${i+1}`}/></div></td></tr>{:else}<tr><td class="cp-empty" colspan="5">{m.t('cyberpunk.create_a_budget_and_assign_money_to_your_categories')}</td></tr>{/each}</tbody><tfoot><tr><th>{m.t('common.total')}</th><td class="cp-number cp-right">{m.money(allocated)}</td><td class="cp-number cp-right">{m.money(spent)}</td><td class="cp-number cp-cyan cp-right">{m.money(allocated+rollover-spent)}</td><td><Meter value={spent} max={allocated} label={m.t('cyberpunk.total_budget_usage')}/></td></tr></tfoot></table></div>
  </Panel>
  {#if m.budgets.length}<div class="cp-budget-links">{#each m.budgets as row}<button class="cp-button ghost small" onclick={() => a.edit('budgets',row)}>{text(row.name)} · {m.t('cyberpunk.edit_allocation')}</button><button class="cp-link cp-red" onclick={()=>a.edit('budget-delete',row)}>{m.t('receipts.delete')}</button>{/each}</div>{/if}
{:else if m.route === 'metas'}
  <div class="cp-toolbar"><div class="cp-tabs">{#each [['',m.t('search.entity_all')],['Activa',m.t('cyberpunk.in_progress')],['Completada',m.t('import.hist_completed')]] as [value,label]}<button class:active={goalFilter === value} onclick={() => goalFilter=value}>{label}</button>{/each}</div><button class="cp-button" onclick={() => a.edit('goals')}>+ {m.t('cyberpunk.new_goal')}</button></div>
  <div class="cp-goal-grid">{#each goals as goal}<Panel title={text(goal.name)} class="cp-goal-panel">{#snippet action()}<button class="cp-icon-button" aria-label={m.t('cyberpunk.edit_goal')} onclick={() => a.edit('goals',goal)}>···</button>{/snippet}<div class="cp-goal-numbers"><strong>{m.money(goal.targetAmount)}</strong><span class="cp-cyan">{Math.round(n(goal.savedAmount)/Math.max(1,n(goal.targetAmount))*100)}%<small>{m.t('cyberpunk.saved')}</small></span></div><Meter value={n(goal.savedAmount)} max={n(goal.targetAmount)} label={text(goal.name)}/><div class="cp-stats plain"><div class="cp-stat"><span>{m.t('dashboard.saved')}</span><b class="cp-number cp-cyan">{m.money(goal.savedAmount)}</b></div><div class="cp-stat"><span>{m.t('dashboard.remaining')}</span><b class="cp-number cp-red">{m.money(Math.max(0,n(goal.targetAmount)-n(goal.savedAmount)))}</b></div><div class="cp-stat"><span>{m.t('cyberpunk.target_date')}</span><b>{m.date(goal.deadline)}</b></div></div><footer class="cp-card-footer"><Icon name="target" size={21}/><span>{goal.status === 'Completada' ? m.t('alerts.filter_goal_completed') : m.t('cyberpunk.every_contribution_counts')}</span><button class="cp-button small ghost" onclick={() => a.edit('withdraw',goal)} disabled={n(goal.savedAmount)<=0}>{m.t('goals.withdraw_btn')}</button><button class="cp-button small ghost" onclick={() => a.edit('fund',goal)} disabled={goal.status === 'Completada'}>+ {m.t('cyberpunk.add_funds')}</button></footer></Panel>{:else}<p class="cp-empty">{m.t('cyberpunk.no_goals_in_this_view')}</p>{/each}</div>
{:else if m.route === 'prestamos'}
  <div class="cp-toolbar"><div class="cp-stats plain"><div class="cp-stat"><span>{m.t('cyberpunk.remaining_principal')}</span><strong class="cp-yellow">{m.money(m.loans.reduce((sum,row)=>sum+n(row.remainingAmount),0))}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.monthly_scheduled_payment')}</span><strong class="cp-red">{m.money(monthly)}</strong></div><div class="cp-stat"><span>{m.t('nav.loans')}</span><strong class="cp-cyan">{m.loans.length}</strong></div></div><button class="cp-button ghost" onclick={() => a.edit('loans')}>+ {m.t('loans.new')}</button></div>
  <div class="cp-loan-list">{#each m.loans as loan}<Panel title={text(loan.name)}><div class="cp-loan-content"><div><span class="cp-muted">{m.t('loans.remaining')}</span><strong class="cp-big cp-yellow">{m.money(loan.remainingAmount)}</strong><Meter value={n(loan.principal)-n(loan.remainingAmount)} max={n(loan.principal)} label={text(loan.name)}/></div><div><span class="cp-muted">{m.t('cyberpunk.annual_interest')}</span><strong class="cp-number">{n(loan.interestRate)}%</strong></div><div><span class="cp-muted">{m.t('loans.term')}</span><strong>{n(loan.term)} {m.t('cyberpunk.months')}</strong></div><div class="cp-loan-actions"><Icon name="credit-card" size={34}/><button class="cp-button small ghost" onclick={() => a.edit('loan-detail',loan)}>{m.t('cyberpunk.view_schedule')} →</button><button class="cp-button small" onclick={() => a.edit('payment',loan)}>{m.t('loans.record_payment')}</button><button class="cp-link" onclick={() => a.edit('loans',loan)}>{m.t('receipts.edit')}</button><button class="cp-link cp-red" onclick={()=>a.edit('loan-delete',loan)}>{m.t('receipts.delete')}</button></div></div></Panel>{:else}<p class="cp-empty">{m.t('cyberpunk.no_loans_yet')}</p>{/each}</div>
  {#if m.loans.length}<Panel title={m.t('loans.schedule_title') + ' · ' + text((m.loans.find(row => row.id === selectedLoan) ?? m.loans[0])?.name)}><div class="cp-table-wrap cp-scroll-table"><table class="cp-table"><thead><tr><th>{m.t('loans.sched_month')}</th><th>{m.t('loans.sched_payment')}</th><th>{m.t('loans.payment_principal')}</th><th>{m.t('loans.payment_interest')}</th><th>{m.t('loans.sched_balance')}</th></tr></thead><tbody>{#each schedule ?? m.schedule as row}<tr><td>{n(row.month)}</td><td class="cp-number">{m.money(row.payment)}</td><td class="cp-number cp-cyan">{m.money(row.principal)}</td><td class="cp-number cp-red">{m.money(row.interest)}</td><td class="cp-number">{m.money(row.remainingBalance)}</td></tr>{/each}</tbody></table></div></Panel>{/if}
{:else}
  <div class="cp-networth-top"><div><span class="cp-muted">{m.t('nav.networth')}</span><strong class="cp-hero-number">{m.money(m.networth.netWorth)}</strong></div><div><span>{m.t('networth.total_assets')}</span><strong class="cp-cyan">{m.money(m.networth.totalAssets)}</strong></div><div><span>{m.t('networth.total_liabilities')}</span><strong class="cp-red">{m.money(m.networth.totalLiabilities)}</strong></div></div>
  <Panel title={m.t('cyberpunk.net_worth_over_time')}>
    {#snippet action()}<div class="cp-tabs">{#each ['1m','6m','1y','all'] as value}<button class:active={range === value} onclick={() => changeRange(value)}>{value}</button>{/each}</div>{/snippet}
    {#if (history ?? m.history).length}<LineChart labels={(history ?? m.history).map(row => m.date(row.date))} datasets={[{label:m.t('nav.networth'),data:(history ?? m.history).map(row => n(row.netWorth)),borderColor:'#6ff4ed',backgroundColor:'#6ff4ed22',fill:true}]} height={245}/>{:else}<p class="cp-empty">{m.t('cyberpunk.history_will_appear_as_daily_snapshots_are_recorded')}</p>{/if}
  </Panel>
  <div class="cp-two">{#each [['assets',m.t('networth.assets_section')],['liabilities',m.t('networth.liabilities_section')]] as [entity,title]}<Panel {title}>{#snippet action()}<button class="cp-button ghost small" onclick={() => a.edit(entity)}>+ {m.t('categories.subcategory_add')}</button>{/snippet}<div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.t('receipts.form_name')}</th><th>{m.t('networth.form_value')}</th><th></th></tr></thead><tbody>{#each rows(m.networth[entity]) as row}<tr><td>{text(row.name)}</td><td class="cp-number" class:cp-red={entity === 'liabilities'}>{m.money(entity === 'assets' ? row.value : row.balance)}</td><td><button class="cp-icon-button" aria-label={m.t('receipts.edit')} onclick={() => a.edit(entity,row)}>···</button></td></tr>{:else}<tr><td colspan="3" class="cp-empty">{m.t('cyberpunk.no_records_yet')}</td></tr>{/each}</tbody></table></div></Panel>{/each}</div>
{/if}
